		state,
		sessionId: session.agent?.sessionId ?? null,
		acknowledgedMessageIds: session.acknowledgedMessageIds,
		result: completed ? session.result!.text : null,
		resultId: completed ? session.result!.id : null,
		error:
			session.agent?.error ??
